-- Rollback for the frozen question audit content patch. NOT part of the deploy.
-- Restores every audited field to its pre-patch value and removes the authored rows.
-- Guarded in both directions: a row edited since the patch landed aborts the block
-- instead of being reverted, so this can never silently discard someone else's work.
-- One atomic block. Safe to re-run, and safe over a partially applied patch.
DO $question_audit$
DECLARE
  plan jsonb := $question_audit_payload${"context_guards":[],"patches":[{"table":"exercises","id":"aabbccdd-6666-1002-0002-e00000000008","before":{"accepted_answers":["さかな"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1002-0004-e00000000006","before":{"accepted_answers":["さかな"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1002-0005-e00000000008","before":{"accepted_answers":["みず"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1002-0006-e00000000004","before":{"accepted_answers":["さかな"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0001-e00000000002","before":{"accepted_answers":["みぎ"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0002-e00000000002","before":{"accepted_answers":["真っ直ぐ","真直ぐ"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0002-e00000000006","before":{"accepted_answers":["えき"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0003-e00000000006","before":{"accepted_answers":["びょういん"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0004-e00000000004","before":{"accepted_answers":["えき"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0004-e00000000006","before":{"accepted_answers":["ぎんこう"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0005-e00000000008","before":{"accepted_answers":["ひだり"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0006-e00000000002","before":{"accepted_answers":["えき"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0006-e00000000006","before":{"accepted_answers":["くうこう"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-1003-0006-e00000000008","before":{"accepted_answers":["みぎ"]},"after":{"accepted_answers":[]}},{"table":"exercises