ble":"exercises","id":"aabbccdd-6666-2006-0001-e00000000002","before":{"accepted_answers":["らいしゅう"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-2006-0003-e00000000008","before":{"accepted_answers":["ゆめ"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-2006-0005-e00000000002","before":{"accepted_answers":["私は旅行します","りょこうします"]},"after":{"accepted_answers":["私は旅行します"]}},{"table":"exercises","id":"aabbccdd-6666-2006-0006-e00000000005","before":{"accepted_answers":["ゆめ"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-2006-0006-e00000000008","before":{"accepted_answers":["あした","あす"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-3001-0002-e00000000005","before":{"accepted_answers":["しゃかい"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-3001-0003-e00000000005","before":{"accepted_answers":["せいじ"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-3001-0004-e00000000005","before":{"accepted_answers":["けいざい"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-3001-0005-e00000000002","before":{"accepted_answers":["しゃかい"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-3001-0006-e00000000002","before":{"accepted_answers":["せいじ"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-3004-0006-e00000000005","before":{"accepted_answers":["たんそ"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-3007-0003-e00000000005","before":{"accepted_answers":["そうぞうして"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-3008-0001-e00000000002","before":{"accepted_answers":["はいけい"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-4001-0001-e00000000008","before":{"accepted_answers":["びょうどう"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-4001-0003-e00000000002","before":{"accepted_answers":["いしき"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-4001-0006-e00000000002","before":{"accepted_answers":["そんざい"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-4001-0006-e00000000008","before":{"accepted_answers":["じゆう"]},"after":{"accepted_answers":[]}},{"table":"exercises","id":"aabbccdd-6666-4003-0005-e00000000002","before":{"accepted_answers":["よさん"]},"after":{"accepted_answers":[]}}]}$question_audit_payload$::jsonb;
  patch jsonb; guard jsonb; current_row jsonb; assignments text; changed integer;
BEGIN
  FOR guard IN SELECT value FROM jsonb_array_elements(plan->'context_guards') LOOP
    IF guard->>'table' <> 'units' THEN RAISE EXCEPTION 'Out-of-scope question audit context'; END IF;
    EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id = $1::uuid FOR SHARE', guard->>'table') INTO current_row USING guard->>'id';
    IF current_row IS NULL OR EXISTS (SELECT 1 FROM jsonb_each(guard->'before') field WHERE current_row->field.key IS DISTINCT FROM field.value) THEN
      RAISE EXCEPTION 'Audited category changed; review before reverting: %/%', guard->>'table', guard->>'id';
    END IF;
  END LOOP;
  FOR patch IN SELECT value FROM jsonb_array_elements(plan->'patches') LOOP
    IF NOT (patch->>'table' = ANY(ARRAY['courses','units','lessons','exercises','cards','grammar_rules','writing_prompts','reading_passages','reading_questions','checkpoint_items'])) THEN
      RAISE EXCEPTION 'Out-of-scope question audit table';
    END IF;
    EXECUTE format('SELECT to_jsonb(t) FROM public.%I t WHERE id = $1::uuid FOR UPDATE', patch->>'table') INTO current_row USING patch->>'id';
    IF current_row IS NULL THEN RAISE EXCEPTION 'Missing audited row %/%', patch->>'table', patch->>'id'; END IF;
    IF NOT EXISTS (SELECT 1 FROM jsonb_each(patch->'after') field WHERE current_row->field.key IS DISTINCT FROM field.value) THEN CONTINUE; END IF;
    IF EXISTS (SELECT 1 FROM jsonb_each(patch->'before') field WHERE current_row->field.key IS DISTINCT FROM field.value) THEN RAISE EXCEPTION 'Audited row changed; review before reverting: %/%', patch->>'table', patch->>'id'; END IF;
    SELECT string_agg(format('%I = (jsonb_populate_record(NULL::public.%I, $1)).%I', key, patch->>'table', key), ', ' ORDER BY key) INTO assignments FROM jsonb_object_keys(patch->'after') key;
    EXECUTE format('UPDATE public.%I SET %s WHERE id = $2::uuid', patch->>'table', assignments) USING patch->'after', patch->>'id';
    GET DIAGNOSTICS changed = ROW_COUNT;
    IF changed <> 1 THEN RAISE EXCEPTION 'Unexpected affected-row count: %', changed; END IF;
  END LOOP;
END
$question_audit$;
